do $do$ declare d jsonb := $j${"topic": {"id": "254abfba-0be1-55fd-a799-860171719b52", "new": true, "name": "Physics · Motion, forces and energy", "summary": "Grade 6 Physics", "sort": 2, "parent": "7bfa0e25-9eef-5444-8919-fb9802196733", "programme": "MYP 1"}, "anchor": "/g6-life-10-revision/", "lessons": [{"id": "b3c4d070-00b6-54ef-8fe7-b836edeacbeb", "ext": "G6-PHYS-MOTION-L1", "title": "Physics · Motion, forces and energy · Lesson 1: Distance, time and speed", "summary": "MYP 1 · Physics · Motion, forces and energy", "url": "/g6-phys-motion-1/", "max": 22, "sort": 11, "msort": 29, "csort": 28, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 6, "n": 6, "ans": ["Distance", "Time", "Distance", "Time", "Time", "Distance"], "tip": "How far, or how long?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Ruler", "Measuring tape or trundle wheel", "Stopwatch", "Clock or calendar"], "tip": "Match the size of what you measure."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["2500", "2 500"], ["180"]], "tips": ["1 km = 1000 m; 1 min = 60 s."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 3, "pts": [["speed = distance", "distance ÷ time", "distance / time", "d/t", "d ÷ t"], ["900 ÷ 60", "900/60", "900 / 60"], ["15 m/s", "15 m s", "15m/s"]], "tips": ["Equation, substitute, answer with unit."]}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["300 ÷ 200", "300/200", "300 / 200"], ["1.5"]], "tips": ["Divide."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["80"], ["40"], ["changed", "changes", "speeds up", "slows", "not constant", "different speeds", "varies"]], "tips": ["Total distance ÷ total time."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 2, "pts": [["stop", "brake", "react", "shorter distance"], ["child", "accident", "in time"]], "tips": ["A slower car travels less distance before it stops."]}]}, "models": {"1": [["Q1", "Brian: 60 ÷ 10 = 6 m/s. Amina: 100 ÷ 16 = 6.25 m/s. So Amina is slightly faster. You need to divide distance by time for each, because they ran different distances."], ["Q2", "Metres, trundle wheel, how far: distance. Seconds, stopwatch, how long: time."]], "2": [["Q3", "Pencil: ruler. Field: tape or trundle wheel. Race: stopwatch. Plant growth: clock or calendar."], ["Q4", "(a) 2.5 × 1000 = 2500 m [1]; (b) 3 × 60 = 180 s [1]."]], "3": [["Q5", "Speed = distance ÷ time [1] = 900 ÷ 60 [1] = 15 m/s [1]."], ["Q6", "300 ÷ 200 [1] = 1.5 m/s [1]."]], "4": [["Q7", "Total distance = 80 km [1]; average speed = 80 ÷ 2 = 40 km/h [1]; it is an average because the matatu's speed changed during the journey (it went slower in the first hour) [1]."]], "5": [["Q8", "At a lower speed a car travels a shorter distance during the driver's reaction time and while braking [1], so it can stop in time if a child runs into the road, preventing accidents [1]."]], "6": [["Exit ticket", "Speed = distance ÷ time; metres per second (m/s)."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_0": "Q5", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "7c1247c1-0245-53cb-a341-f76533a9181f", "ext": "G6-PHYS-MOTION-L2", "title": "Physics · Motion, forces and energy · Lesson 2: Acceleration and force: cause and consequence", "summary": "MYP 1 · Physics · Motion, forces and energy", "url": "/g6-phys-motion-2/", "max": 24, "sort": 12, "msort": 30, "csort": 29, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Push", "Pull", "Pull", "Push", "Pull"], "tip": "Is the force away from you or towards something?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Gravity", "Friction", "Air resistance", "Upthrust", "Tension"], "tip": "Where does it act?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["push", "force", "punch"], ["direction", "changes direction", "goes back"], ["speed", "slows", "shape", "squash", "stops", "faster"]], "tips": ["Cause first, then two results."]}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 1, "pts": [["change in speed", "speeding up", "gets faster", "increase in speed", "change of speed"]], "tips": ["What happens to the speed?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["Balanced", "Unbalanced", "Balanced", "Unbalanced", "Balanced"], "tip": "Is the motion changing?"}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["50 n", "50n"], ["towards team a", "towards a", "a wins", "accelerates"]], "tips": ["Subtract; bigger wins."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["grip", "tyre", "brake", "walk", "shoes", "match"], ["wear", "heat", "engine", "machine", "waste", "slow"], ["oil", "lubric", "grease", "smooth", "wheels", "ball bearing"]], "tips": ["Good friction, bad friction, fix."]}]}, "models": {"1": [["Q1", "It starts moving because of your push (force). It slows down because friction from the floor and air resistance act against it. It may change direction if it hits a wall (a push from the wall). Each change has a force as its cause."], ["Q2", "Kicking and closing: push. Drawer, gravity and magnet: pull."]], "2": [["Q3", "Mango: gravity. Brakes: friction. Parachute: air resistance. Boat: upthrust. Rope: tension."]], "3": [["Q4", "The cause is a push from the goalkeeper's fist (a force) [1]; consequences: the ball changes direction [1] and its speed changes (and its shape is squashed for a moment) [1]."], ["Q5", "Acceleration is a change in speed (getting faster) [1]."]], "4": [["Q6", "No change in motion: balanced. Speeding up or slowing down: unbalanced."], ["Q7", "Resultant force = 500 − 450 = 50 N [1]; the rope moves towards team A (it accelerates in A's direction) [1]."]], "5": [["Q8", "Useful: friction between tyres and the road lets a bicycle grip and brake [1]; a problem: friction in a car engine wears out parts and wastes energy as heat [1]; people reduce it by adding oil (lubricant) or using smooth surfaces and ball bearings [1]."]], "6": [["Exit ticket", "A force is the cause and a change in motion (speed, direction or shape) is the consequence."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q4", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "cbf5e49e-ce4f-52b7-bef7-53ae56bfbabc", "ext": "G6-PHYS-MOTION-L3", "title": "Physics · Motion, forces and energy · Lesson 3: Plotting distance–time and speed–time graphs", "summary": "MYP 1 · Physics · Motion, forces and energy", "url": "/g6-phys-motion-3/", "max": 20, "sort": 13, "msort": 31, "csort": 30, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 3, "n": 3, "ans": ["x-axis (horizontal)", "y-axis (vertical)", "y-axis (vertical)"], "tip": "Time always goes along the bottom."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 3, "pts": [["constant speed", "steady speed", "same speed", "5 m/s"], ["stopped", "stationary", "not moving", "flat"], ["faster", "steeper", "10 m/s", "quicker"]], "tips": ["Slope, flat, steeper."]}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["150 ÷ 30", "150/30", "150 / 30"], ["5"]], "tips": ["Distance ÷ time for that section."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Stationary", "Constant speed", "Speeding up", "Slowing down"], "tip": "Steepness = speed."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["accelerat", "speeding up", "speeds up"], ["constant", "steady", "same speed", "10 m/s"], ["decelerat", "slowing", "slows", "stops"]], "tips": ["Up, flat, down."]}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["stationary", "stopped", "not moving", "distance not changing"], ["constant speed", "steady speed", "same speed", "speed not changing"]], "tips": ["Read the y-axis."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["units", "label"], ["scale", "bigger", "more than half", "whole page"], ["ruler", "best fit", "straight line", "smooth"]], "tips": ["Labels, scale, line."]}]}, "models": {"1": [["Q1", "For example: a sloping line while walking, a flat line while waiting for the matatu, a steeper line while riding in the matatu, then a gentle slope walking from the stage to school."], ["Q2", "Time: x-axis. Distance or speed: y-axis."]], "2": [["Q3", "0–30 s: moving at a constant speed (5 m/s) [1]; 30–50 s: stopped (stationary), the line is flat [1]; 50–60 s: moving faster, the line is steeper (10 m/s) [1]."], ["Q4", "150 ÷ 30 [1] = 5 m/s [1]."]], "3": [["Q5", "Flat: stationary. Straight slope: constant speed. Steeper curve: speeding up. Flattening curve: slowing down."]], "4": [["Q6", "0–10 s: accelerating (speeding up from 0 to 10 m/s) [1]; 10–20 s: moving at a constant speed of 10 m/s [1]; 20–30 s: decelerating until it stops [1]."], ["Q7", "On a distance–time graph a flat line means the distance is not changing, so the object is stationary [1]; on a speed–time graph a flat line means the speed is not changing: constant speed [1]."]], "5": [["Q8", "Label both axes with the quantity and unit, e.g. Time (s) [1]; choose a larger scale so the graph uses more than half of the paper [1]; draw a straight line or smooth curve of best fit with a ruler instead of joining dots [1]."]], "6": [["Exit ticket", "The object is stationary (not moving)."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q2_1": "Q4", "q4_0": "Q6", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "e034a09f-2f78-51a0-ac5b-cabb352994be", "ext": "G6-PHYS-MOTION-L4", "title": "Physics · Motion, forces and energy · Lesson 4: Speed in real life: using speed = distance ÷ time", "summary": "MYP 1 · Physics · Motion, forces and energy", "url": "/g6-phys-motion-4/", "max": 17, "sort": 14, "msort": 32, "csort": 31, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 3, "n": 3, "ans": ["distance = speed × time", "speed = distance ÷ time", "time = distance ÷ speed"], "tip": "Which quantity is missing?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["60 × 2.5", "60 x 2.5", "60*2.5"], ["150"]], "tips": ["d = s × t."]}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["340 × 4", "340 x 4", "340*4"], ["1360"]], "tips": ["d = s × t."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 3, "pts": [["18 ÷ 12", "18/12", "18 / 12"], ["1.5"], ["90"]], "tips": ["t = d ÷ s, then × 60."]}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 1, "pts": [["20"]], "tips": ["Divide by 3.6."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["2 × 8", "2 x 8", "16"], ["steeper", "more steep"], ["faster", "double", "twice", "32"]], "tips": ["Predict, then compare slopes."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["2 ÷ 60", "2/60", "0.033", "33.3 m/s", "2000 ÷ 60", "33"], ["120"], ["speeding", "over the limit", "too fast", "yes"]], "tips": ["Convert 60 s to hours, or find m/s first."]}]}, "models": {"1": [["Q1", "480 ÷ 100 = 4.8 hours, about 4 hours 48 minutes. We divided the distance by the speed."], ["Q2", "Missing distance: d = s × t. Missing speed: s = d ÷ t. Missing time: t = d ÷ s."]], "2": [["Q3", "Distance = 60 × 2.5 [1] = 150 km [1]."], ["Q4", "Distance = 340 × 4 [1] = 1360 m [1]."]], "3": [["Q5", "Time = 18 ÷ 12 [1] = 1.5 hours [1] = 90 minutes [1]."], ["Q6", "72 ÷ 3.6 = 20 m/s [1]."]], "4": [["Q7", "Distance = 2 × 8 = 16 m [1]; at 4 m/s the line would be steeper [1], because the car goes twice as far (32 m) in the same time [1]."]], "5": [["Q8", "Speed = 2000 m ÷ 60 s = 33.3 m/s [1]; 33.3 × 3.6 = 120 km/h [1]; yes, the car was speeding, because 120 km/h is above the 100 km/h limit [1]."]], "6": [["Exit ticket", "240 ÷ 4 = 60 km/h."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q2_1": "Q4", "q3_0": "Q5", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "71b11aff-1d8f-5128-91df-edd4b2de22b3", "ext": "G6-PHYS-MOTION-L5", "title": "Physics · Motion, forces and energy · Lesson 5: Investigating motion: a ramp experiment", "summary": "MYP 1 · Physics · Motion, forces and energy", "url": "/g6-phys-motion-5/", "max": 22, "sort": 15, "msort": 33, "csort": 32, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 4, "n": 4, "ans": ["Independent variable", "Dependent variable", "Control variable", "Control variable"], "tip": "Change, measure, keep the same."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["higher", "steeper", "greater height"], ["faster", "more speed", "greater speed", "energy", "gravity"]], "tips": ["If… then… because…."]}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 4, "pts": [["ramp", "books", "height", "set up", "prop"], ["release", "let go", "do not push", "start line"], ["stopwatch", "time", "measure"], ["repeat", "three times", "mean", "different heights"]], "tips": ["Set up, release, time, repeat."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 2, "pts": [["2.0", "2 s", "mean 2"], ["0.5"]], "tips": ["Mean, then 1 ÷ mean."]}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 3, "pts": [["1.1"], ["0.91", "0.9", "0.909"], ["higher", "faster", "increase", "more speed"]], "tips": ["Mean time first."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["speed increases", "increases", "higher", "faster"], ["supports", "agree", "correct", "yes"], ["energy", "gravity", "potential", "kinetic"]], "tips": ["Pattern, hypothesis, reason."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["reaction time", "stopwatch", "human"], ["light gate", "video", "slow motion", "longer distance", "phone"], ["swerve", "direction", "straight", "few heights", "only three", "push"], ["rails", "guide", "more heights", "more repeats", "track", "same person"]], "tips": ["Timing error, and one more."]}]}, "models": {"1": [["Q1", "The height (or angle) of the ramp, the surface of the ramp (smooth or rough, e.g. covered with cloth), and the mass of the car (adding plasticine). Each could be investigated as the independent variable."], ["Q2", "Height: independent. Time: dependent. Same car and same start line: control."]], "2": [["Q3", "If the ramp is higher, then the toy car will travel faster [1], because it starts with more gravitational potential energy, which turns into more kinetic energy (gravity pulls it harder along the slope) [1]."], ["Q4", "Prop the ramp on books so its top is 10 cm high [1]; release the car from the start line without pushing [1]; use a stopwatch to time how long it takes to travel 1 m along the floor [1]; repeat three times, then change the height to 20, 30, 40 and 50 cm [1]."]], "3": [["Q5", "Mean time = (2.1 + 2.0 + 1.9) ÷ 3 = 2.0 s [1]; average speed = 1 ÷ 2.0 = 0.5 m/s [1]."], ["Q6", "Mean time at 30 cm = 1.1 s [1]; speed = 1 ÷ 1.1 = 0.91 m/s [1]; the higher the ramp, the faster the car travelled [1]."]], "4": [["Q7", "As the height of the ramp increases, the average speed of the car increases [1]; this supports my hypothesis [1], because a higher ramp gives the car more gravitational potential energy to change into kinetic energy [1]."]], "5": [["Q8", "Reaction time when starting and stopping the stopwatch is large compared with the short times [1]; use light gates, a phone slow-motion video or a longer distance [1]; the car sometimes swerved and only three heights were tested [1]; use a guide track and test more heights with more repeats [1]."]], "6": [["Exit ticket", "Independent: ramp height. Dependent: time to travel 1 m (average speed)."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q2_1": "Q4", "q3_0": "Q5", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "3f538def-1f11-5fa9-8f57-6c1a78d890da", "ext": "G6-PHYS-MOTION-L6", "title": "Physics · Motion, forces and energy · Lesson 6: Energy: what it is, its types and sources", "summary": "MYP 1 · Physics · Motion, forces and energy", "url": "/g6-phys-motion-6/", "max": 26, "sort": 16, "msort": 34, "csort": 33, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 4, "n": 4, "ans": ["Yes", "Yes", "No", "Yes"], "tip": "Is something moving, heating, lighting or sounding?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Kinetic", "Gravitational potential", "Elastic potential", "Chemical", "Thermal", "Chemical"], "tip": "Moving, high up, stretched, food or fuel, hot?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["chemical", "battery"], ["light", "electrical", "thermal", "heat"]], "tips": ["Battery → bulb."]}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["gravitational", "potential"], ["kinetic"]], "tips": ["High → falling."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 6, "n": 6, "ans": ["Renewable", "Non-renewable", "Renewable", "Non-renewable", "Renewable", "Non-renewable"], "tip": "Will it run out?"}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["renewable", "free", "sunny", "clean", "no pollution", "rural", "off-grid"], ["night", "cloud", "cost", "expensive", "battery", "weather"]], "tips": ["Good and bad."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["solar", "wind", "geothermal", "hydro", "biomass", "biogas", "fossil", "diesel", "charcoal", "nuclear"], ["how it works", "works", "turbine", "convert", "generates"], ["advantage", "renewable", "clean", "cheap"], ["disadvantage", "cost", "pollut", "weather", "run out", "environment"]], "tips": ["Source, how it works, pros, cons."]}]}, "models": {"1": [["Q1", "Waking and walking: chemical energy from food. Lighting the stove: chemical energy in gas or charcoal. Turning on a light: electrical energy. Riding a matatu: chemical energy in diesel. Phone screen: chemical energy in the battery."], ["Q2", "Rolling, boiling and sound use energy; a still book is not using energy to change."]], "2": [["Q3", "Moving: kinetic. High up: gravitational. Stretched: elastic. Food and battery: chemical. Hot: thermal."]], "3": [["Q4", "Chemical energy in the battery is transferred as electrical energy [1] and becomes light and some thermal energy in the bulb [1]."], ["Q5", "Gravitational potential energy [1] changes into kinetic energy as it falls [1]."]], "4": [["Q6", "Geothermal, solar and wind: renewable. Diesel, coal and gas: non-renewable."], ["Q7", "Advantage: it is renewable and clean, and Kenya has lots of sunshine, even in remote areas [1]; disadvantage: it does not work at night or on cloudy days without expensive batteries [1]."]], "5": [["Q8", "Source: geothermal energy at Olkaria [1]; how it works: hot steam from underground turns turbines to generate electricity [1]; advantage: it is renewable and works day and night [1]; disadvantage: drilling is expensive and it only works in volcanic areas like the Rift Valley [1]."]], "6": [["Exit ticket", "Energy is the capacity to move an object or cause change. Geothermal (Olkaria) and wind (Lake Turkana) (also solar, hydroelectric)."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q4", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "40bd0e8f-330f-5c0d-a495-7308cac1e128", "ext": "G6-PHYS-MOTION-L7", "title": "Physics · Motion, forces and energy · Lesson 7: Kinetic and gravitational potential energy; conservation of energy", "summary": "MYP 1 · Physics · Motion, forces and energy", "url": "/g6-phys-motion-7/", "max": 18, "sort": 17, "msort": 35, "csort": 34, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 4, "n": 4, "ans": ["More energy", "Less energy", "More energy", "Less energy"], "tip": "KE: mass and speed. GPE: mass and height."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["3 × 10 × 4", "3 x 10 x 4", "m × g × h", "mgh"], ["120"]], "tips": ["GPE = mgh."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["0.5 × 50 × 36", "½ × 50 × 6²", "0.5 x 50 x 36", "25 × 36", "½ × 50 × 36"], ["900"]], "tips": ["Square the speed first."]}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["squared", "v²", "v2"], ["four times", "4 times", "quadruple", "double"]], "tips": ["Look at the equation."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["cannot be created", "not created", "cannot be destroyed", "not destroyed"], ["transferred", "changed", "converted", "total stays"]], "tips": ["Two parts."]}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["heat", "thermal", "sound"], ["friction", "air resistance", "surroundings", "not destroyed", "wasted"]], "tips": ["It did not disappear."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["2 × 10 × 20", "2 x 10 x 20", "mgh"], ["400"], ["v² = 400", "v2 = 400", "½ × 2 × v²", "0.5 × 2 × v", "v² = 400"], ["20 m/s", "20m/s", "v = 20"]], "tips": ["GPE → KE → speed."]}]}, "models": {"1": [["Q1", "It moves fastest at the bottom, where it has the most kinetic energy, and stops for an instant at each end, where it is highest and has the most gravitational potential energy. Energy keeps changing between GPE and KE. Over time it slows because of air resistance and friction."], ["Q2", "Lorry: more KE. Low shelf: less GPE. Faster runner: more KE. Lighter book: less GPE."]], "2": [["Q3", "GPE = 3 × 10 × 4 [1] = 120 J [1]."]], "3": [["Q4", "KE = ½ × 50 × 6² = 0.5 × 50 × 36 [1] = 900 J [1]."], ["Q5", "KE depends on speed squared [1], so doubling the speed makes the KE four times bigger, but doubling the mass only doubles it [1]."]], "4": [["Q6", "Energy cannot be created or destroyed [1]; it can only be transferred from one store to another, so the total stays the same [1]."], ["Q7", "Some energy was transferred as heat and sound when the ball hit the ground [1], and some was lost to air resistance; it was not destroyed, just spread into the surroundings [1]."]], "5": [["Q8", "(a) GPE = 2 × 10 × 20 [1] = 400 J; (b) KE = 400 J, because GPE lost = KE gained [1]; (c) ½ × 2 × v² = 400, so v² = 400 [1], v = 20 m/s [1]."]], "6": [["Exit ticket", "Energy cannot be created or destroyed, only transferred from one store to another."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q3_0": "Q4", "q3_1": "Q5", "q4_0": "Q6", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "1dabe3a3-b88f-5995-b57f-43d96e2565ae", "ext": "G6-PHYS-MOTION-L8", "title": "Physics · Motion, forces and energy · Lesson 8: Newton's laws of motion", "summary": "MYP 1 · Physics · Motion, forces and energy", "url": "/g6-phys-motion-8/", "max": 19, "sort": 18, "msort": 36, "csort": 35, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["First law (inertia)", "Third law (action and reaction)", "Second law (F = m × a)", "First law (inertia)", "Third law (action and reaction)"], "tip": "Inertia, F = ma, or pairs?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 3, "pts": [["keep moving", "continue moving", "inertia", "carry on"], ["brakes", "stops", "crash", "suddenly"], ["force", "seat belt", "stop them", "hold"]], "tips": ["The car stops; the passenger…?"]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["300 ÷ 60", "300/60", "300 / 60"], ["5"]], "tips": ["a = F ÷ m."]}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["1200 × 2", "1200 x 2", "1200*2"], ["2400"]], "tips": ["F = m × a."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["push", "water", "backwards", "back"], ["forward", "pushes", "equal", "opposite"]], "tips": ["Action, reaction."]}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["gas", "exhaust", "pushes gas", "fuel"], ["equal", "opposite", "pushes the rocket", "reaction", "forward", "up"]], "tips": ["What does the rocket push?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["longer", "more time", "slow", "gradual"], ["smaller force", "less force", "reduce force", "are smaller", "force on the person"], ["crumple", "helmet", "foam", "squash", "absorb"]], "tips": ["Stopping over a longer time needs less force."]}]}, "models": {"1": [["Q1", "The coin drops into the cup. The card is flicked away, but the coin tends to stay where it is (inertia: Newton's first law). No horizontal force acts on it long enough to move it sideways, so gravity pulls it straight down into the cup."], ["Q2", "Lurching and still ball: first law. Rocket and walking: third law. Heavier wheelbarrow: second law."]], "2": [["Q3", "If the car stops suddenly, the passengers keep moving forward at the same speed (inertia) [1], because no force has acted on them when the car braked [1]; the seat belt provides the force that stops them, so they do not hit the windscreen [1]."]], "3": [["Q4", "a = F ÷ m = 300 ÷ 60 [1] = 5 m/s² [1]."], ["Q5", "F = 1200 × 2 [1] = 2400 N [1]."]], "4": [["Q6", "The swimmer pushes the water backwards with their arms and legs [1]; the water pushes the swimmer forwards with an equal and opposite force [1]."], ["Q7", "The rocket pushes hot exhaust gas out backwards [1]; the gas pushes the rocket forwards with an equal and opposite force, so it does not need air [1]."]], "5": [["Q8", "A helmet's foam and a car's crumple zone squash in a crash, absorbing energy [1]; they make the head or car stop over a longer time [1], so the deceleration and the force on the person are smaller, causing less injury [1]."]], "6": [["Exit ticket", "Force = mass × acceleration (F = m × a)."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q3_0": "Q4", "q3_1": "Q5", "q4_0": "Q6", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "e12773ca-11bd-5af3-b2a8-78f6c5641e45", "ext": "G6-PHYS-MOTION-L9", "title": "Physics · Motion, forces and energy · Lesson 9: Machines and climate change", "summary": "MYP 1 · Physics · Motion, forces and energy", "url": "/g6-phys-motion-9/", "max": 20, "sort": 19, "msort": 37, "csort": 36, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Lever", "Pulley", "Inclined plane", "Wheel and axle", "Lever"], "tip": "Bar and pivot, rope and wheel, slope, or big wheel on small axle?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 3, "pts": [["450 × 0.3", "450 x 0.3", "135"], ["÷ 1.2", "/ 1.2", "effort × 1.2", "effort x 1.2"], ["112.5", "113"]], "tips": ["Clockwise moment = anticlockwise moment."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["350 ÷ 1000", "350/1000", "0.35"], ["35"], ["heat", "thermal", "sound", "wasted"]], "tips": ["Useful out ÷ total in × 100."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["burn", "diesel", "fossil fuel", "combust"], ["carbon dioxide", "co2", "greenhouse gas"], ["trap", "heat", "warm", "temperature"]], "tips": ["Fuel → gas → effect."]}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["drought", "rain", "crop", "food", "livestock"], ["flood", "glacier", "water", "disease", "malaria", "heat", "sea level"]], "tips": ["Think about farming and weather."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["less carbon", "co2", "no emissions", "climate", "renewable", "clean"], ["cheaper", "efficient", "fuel cost", "quiet", "less noise", "air pollution", "maintenance"], ["cost", "expensive", "charging", "battery", "range", "rural", "electricity"], ["i think", "overall", "conclusion", "should", "because"]], "tips": ["Two pros, one con, conclusion."]}]}, "models": {"1": [["Q1", "The spoon acts as a lever: the rim of the tin is the pivot. A small force on the long handle makes a large force on the lid near the pivot."], ["Q2", "Crowbar and wheelbarrow: lever. Flag: pulley. Ramp: inclined plane. Bicycle: wheel and axle."]], "2": [["Q3", "Moment of the load = 450 × 0.3 = 135 N m [1]; effort × 1.2 = 135 [1]; effort = 112.5 N [1]."]], "3": [["Q4", "Efficiency = 350 ÷ 1000 [1] × 100 = 35% [1]; the other 650 J is wasted as heat and sound [1]."]], "4": [["Q5", "The engine burns diesel, a fossil fuel [1], which releases carbon dioxide, a greenhouse gas [1]; more carbon dioxide in the atmosphere traps more heat, warming the Earth and changing the climate [1]."], ["Q6", "Longer droughts kill livestock and crops in northern Kenya, causing hunger [1]; heavier floods destroy homes, and the glaciers on Mount Kenya are melting, reducing river water [1]."]], "5": [["Q7", "Electric boda bodas produce no exhaust and Kenya's electricity is mostly renewable, so they reduce carbon dioxide emissions [1]; electric motors are more efficient, so running costs are lower, and they are quieter with no air pollution in towns [1]; however, they cost more to buy and charging points are few in rural areas [1]; overall I think the government should support them with loans and charging stations because they help riders and the climate [1]."]], "6": [["Exit ticket", "Lever and pulley. A lever lets a small effort far from the pivot lift a large load near the pivot."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q3_0": "Q4", "q4_0": "Q5", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}], "quizzes": [{"id": "8aa325e1-df8d-540b-8b9d-3b9fb344705b", "title": "Grade 6 · Physics · Motion, forces and energy · Lesson 1: Distance, time and speed · Criteria A and C exam-style questions", "instr": "Exam-style questions for the lesson \"Distance, time and speed\" (MYP 1, Grade 6 Physics). Criterion A: Knowing and understanding. Criterion C: Processing and evaluating. 8 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "93ce0938-9c0c-5dd8-b8d5-0ffd0a1c6563", "title": "Grade 6 · Physics · Motion, forces and energy · Lesson 2: Acceleration and force: cause and consequence · Criteria A and C exam-style questions", "instr": "Exam-style questions for the lesson \"Acceleration and force: cause and consequence\" (MYP 1, Grade 6 Physics). Criterion A: Knowing and understanding. Criterion C: Processing and evaluating. 10 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "b0a042c3-329b-50d9-baea-40531f6f5d36", "title": "Grade 6 · Physics · Motion, forces and energy · Lesson 3: Plotting distance–time and speed–time graphs · Criterion C exam-style questions", "instr": "Exam-style questions for the lesson \"Plotting distance–time and speed–time graphs\" (MYP 1, Grade 6 Physics). Criterion C: Processing and evaluating. 11 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "7b4c107e-f344-5b55-a083-e0a7d04c77b5", "title": "Grade 6 · Physics · Motion, forces and energy · Lesson 4: Speed in real life: using speed = distance ÷ time · Criteria A and C exam-style questions", "instr": "Exam-style questions for the lesson \"Speed in real life: using speed = distance ÷ time\" (MYP 1, Grade 6 Physics). Criterion A: Knowing and understanding. Criterion C: Processing and evaluating. 8 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "1a5927e6-1180-5aeb-a787-8d1f541afc11", "title": "Grade 6 · Physics · Motion, forces and energy · Lesson 5: Investigating motion: a ramp experiment · Criteria B and C exam-style questions", "instr": "Exam-style questions for the lesson \"Investigating motion: a ramp experiment\" (MYP 1, Grade 6 Physics). Criterion B: Inquiring and designing. Criterion C: Processing and evaluating. 9 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "cf6d16f0-3bb9-540b-8954-be5e9214289d", "title": "Grade 6 · Physics · Motion, forces and energy · Lesson 6: Energy: what it is, its types and sources · Criteria A and D exam-style questions", "instr": "Exam-style questions for the lesson \"Energy: what it is, its types and sources\" (MYP 1, Grade 6 Physics). Criterion A: Knowing and understanding. Criterion D: Reflecting on the impacts of science. 10 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "e741023c-d5d5-525b-abc9-cc6a619d59f6", "title": "Grade 6 · Physics · Motion, forces and energy · Lesson 7: Kinetic and gravitational potential energy; conservation of energy · Criteria A and C exam-style questions", "instr": "Exam-style questions for the lesson \"Kinetic and gravitational potential energy; conservation of energy\" (MYP 1, Grade 6 Physics). Criterion A: Knowing and understanding. Criterion C: Processing and evaluating. 8 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "86bb94a7-b76d-5e96-b976-ccf374c3e0c2", "title": "Grade 6 · Physics · Motion, forces and energy · Lesson 8: Newton's laws of motion · Criteria A and C exam-style questions", "instr": "Exam-style questions for the lesson \"Newton's laws of motion\" (MYP 1, Grade 6 Physics). Criterion A: Knowing and understanding. Criterion C: Processing and evaluating. 8 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "5c7c6431-5c2f-5d0f-8341-0dc7e7735c81", "title": "Grade 6 · Physics · Motion, forces and energy · Lesson 9: Machines and climate change · Criteria A, C and D exam-style questions", "instr": "Exam-style questions for the lesson \"Machines and climate change\" (MYP 1, Grade 6 Physics). Criterion A: Knowing and understanding. Criterion C: Processing and evaluating. Criterion D: Reflecting on the impacts of science. 9 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}], "questions": [{"id": "e54f6958-eb3c-5eb1-af3c-dc8ac6b49525", "quiz": "8aa325e1-df8d-540b-8b9d-3b9fb344705b", "pos": 1, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nMatch the quantity to its SI unit.\nDistance", "options": ["Metre (m)", "Second (s)", "Metres per second (m/s)"], "marks": 1, "section": "Criterion A", "correct": 0, "model": "Distance: m; time: s; speed: m/s.", "points": null}, {"id": "46de5de5-facc-5e4d-94b9-c1d81823ef5d", "quiz": "8aa325e1-df8d-540b-8b9d-3b9fb344705b", "pos": 2, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nMatch the quantity to its SI unit.\nTime", "options": ["Metre (m)", "Second (s)", "Metres per second (m/s)"], "marks": 1, "section": "Criterion A", "correct": 1, "model": "Distance: m; time: s; speed: m/s.", "points": null}, {"id": "7f9d4766-2218-5312-b725-4c9f0e847c4d", "quiz": "8aa325e1-df8d-540b-8b9d-3b9fb344705b", "pos": 3, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nMatch the quantity to its SI unit.\nSpeed", "options": ["Metre (m)", "Second (s)", "Metres per second (m/s)"], "marks": 1, "section": "Criterion A", "correct": 2, "model": "Distance: m; time: s; speed: m/s.", "points": null}, {"id": "8c958d33-8c5c-5712-85e4-4dd9b87be171", "quiz": "8aa325e1-df8d-540b-8b9d-3b9fb344705b", "pos": 4, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDefine speed.", "options": [], "marks": 1, "section": "Criterion A", "correct": null, "model": "Speed is the distance travelled per unit of time [1].", "points": [{"text": "Speed is the distance travelled per unit of time", "any": ["distance", "how far", "per unit time", "per second", "divided by time"], "all": [], "marks": 1}]}, {"id": "ae4613e5-c48e-53e3-917a-cc6a51c1ba4a", "quiz": "8aa325e1-df8d-540b-8b9d-3b9fb344705b", "pos": 5, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nA car travels 1200 m in 40 s. Calculate its speed.", "options": [], "marks": 2, "section": "Criterion C", "correct": null, "model": "1200 ÷ 40 [1] = 30 m/s [1].", "points": [{"text": "1200 ÷ 40", "any": ["1200 ÷ 40", "1200/40", "1200 / 40"], "all": [], "marks": 1}, {"text": "= 30 m/s", "any": ["30"], "all": [], "marks": 1}]}, {"id": "3e20d99a-0ea7-577a-b2f3-613cce375b6c", "quiz": "8aa325e1-df8d-540b-8b9d-3b9fb344705b", "pos": 6, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nCalculate the time taken for a runner moving at 5 m/s to cover 400 m.", "options": [], "marks": 2, "section": "Criterion C", "correct": null, "model": "Time = distance ÷ speed = 400 ÷ 5 [1] = 80 s [1].", "points": [{"text": "Time = distance ÷ speed = 400 ÷ 5", "any": ["400 ÷ 5", "400/5", "distance ÷ speed", "distance / speed"], "all": [], "marks": 1}, {"text": "= 80 s", "any": ["80"], "all": [], "marks": 1}]}, {"id": "6fcb98ef-e074-53ee-a9f9-340e9d3e6c2b", "quiz": "93ce0938-9c0c-5dd8-b8d5-0ffd0a1c6563", "pos": 1, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDefine force and state its unit.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "A force is a push or a pull [1]; it is measured in newtons (N) [1].", "points": [{"text": "A force is a push or a pull", "any": ["push", "pull"], "all": [], "marks": 1}, {"text": "It is measured in newtons (N)", "any": ["newton"], "all": [], "marks": 1}]}, {"id": "b7356475-d8c1-5963-a535-06591c270cbf", "quiz": "93ce0938-9c0c-5dd8-b8d5-0ffd0a1c6563", "pos": 2, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nState three effects (consequences) a force can have on an object.", "options": [], "marks": 3, "section": "Criterion A", "correct": null, "model": "It can make an object start moving or speed up [1]; slow down or stop (or change direction) [1]; change its shape [1].", "points": [{"text": "It can make an object start moving or speed up", "any": ["start", "move", "speed up", "faster"], "all": [], "marks": 1}, {"text": "Slow down or stop (or change direction)", "any": ["slow", "stop", "direction"], "all": [], "marks": 1}, {"text": "Change its shape", "any": ["shape", "squash", "stretch", "bend", "direction"], "all": [], "marks": 1}]}, {"id": "c1cdabd2-6707-5c23-8ab4-82d204bc7257", "quiz": "93ce0938-9c0c-5dd8-b8d5-0ffd0a1c6563", "pos": 3, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nBalanced or unbalanced forces?\nA ball resting on the ground", "options": ["Balanced", "Unbalanced"], "marks": 1, "section": "Criterion A", "correct": 0, "model": "Resting and steady speed: balanced. Speeding up: unbalanced.", "points": null}, {"id": "a279f4e8-9708-597e-9c40-8615a6e38dba", "quiz": "93ce0938-9c0c-5dd8-b8d5-0ffd0a1c6563", "pos": 4, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nBalanced or unbalanced forces?\nA falling stone speeding up", "options": ["Balanced", "Unbalanced"], "marks": 1, "section": "Criterion A", "correct": 1, "model": "Resting and steady speed: balanced. Speeding up: unbalanced.", "points": null}, {"id": "d9e7c4b3-5e2a-5077-b38e-a00dfa48067d", "quiz": "93ce0938-9c0c-5dd8-b8d5-0ffd0a1c6563", "pos": 5, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nBalanced or unbalanced forces?\nA bus moving at a steady speed", "options": ["Balanced", "Unbalanced"], "marks": 1, "section": "Criterion A", "correct": 0, "model": "Resting and steady speed: balanced. Speeding up: unbalanced.", "points": null}, {"id": "fe223d1f-d8d6-58e6-a5ef-c294ff70d73f", "quiz": "93ce0938-9c0c-5dd8-b8d5-0ffd0a1c6563", "pos": 6, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nA car speeds up from 0 to 20 m/s in 4 s. Calculate its acceleration.", "options": [], "marks": 2, "section": "Criterion C", "correct": null, "model": "Acceleration = change in speed ÷ time = 20 ÷ 4 [1] = 5 m/s² [1].", "points": [{"text": "Acceleration = change in speed ÷ time = 20 ÷ 4", "any": ["20 ÷ 4", "20/4", "20 / 4"], "all": [], "marks": 1}, {"text": "= 5 m/s²", "any": ["5"], "all": [], "marks": 1}]}, {"id": "2024c29d-94fe-5060-b260-2d644338d558", "quiz": "b0a042c3-329b-50d9-baea-40531f6f5d36", "pos": 1, "kind": "mcq", "prompt": "[Criterion C: Processing and evaluating]\nOn a distance–time graph, what does each shape mean?\nHorizontal line", "options": ["Stationary", "Constant speed", "Faster"], "marks": 1, "section": "Criterion C", "correct": 0, "model": "Flat: stationary; slope: constant speed; steeper: faster.", "points": null}, {"id": "78a0141d-3f8e-595f-94af-683fe6a4e248", "quiz": "b0a042c3-329b-50d9-baea-40531f6f5d36", "pos": 2, "kind": "mcq", "prompt": "[Criterion C: Processing and evaluating]\nOn a distance–time graph, what does each shape mean?\nStraight sloping line", "options": ["Stationary", "Constant speed", "Faster"], "marks": 1, "section": "Criterion C", "correct": 1, "model": "Flat: stationary; slope: constant speed; steeper: faster.", "points": null}, {"id": "b2a5e064-d712-598a-b4f7-0e37d3222f54", "quiz": "b0a042c3-329b-50d9-baea-40531f6f5d36", "pos": 3, "kind": "mcq", "prompt": "[Criterion C: Processing and evaluating]\nOn a distance–time graph, what does each shape mean?\nSteeper straight line", "options": ["Stationary", "Constant speed", "Faster"], "marks": 1, "section": "Criterion C", "correct": 2, "model": "Flat: stationary; slope: constant speed; steeper: faster.", "points": null}, {"id": "a748739d-33a5-5f05-b4ac-7c75db6691b2", "quiz": "b0a042c3-329b-50d9-baea-40531f6f5d36", "pos": 4, "kind": "mcq", "prompt": "[Criterion C: Processing and evaluating]\nOn a speed–time graph, what does each shape mean?\nHorizontal line above zero", "options": ["Constant speed", "Accelerating", "Decelerating"], "marks": 1, "section": "Criterion C", "correct": 0, "model": "Flat: constant speed; up: accelerating; down: decelerating.", "points": null}, {"id": "8ce09841-2ee8-55c0-802a-b7e665ab6e8f", "quiz": "b0a042c3-329b-50d9-baea-40531f6f5d36", "pos": 5, "kind": "mcq", "prompt": "[Criterion C: Processing and evaluating]\nOn a speed–time graph, what does each shape mean?\nLine sloping upwards", "options": ["Constant speed", "Accelerating", "Decelerating"], "marks": 1, "section": "Criterion C", "correct": 1, "model": "Flat: constant speed; up: accelerating; down: decelerating.", "points": null}, {"id": "f8e18d6e-22e8-580c-bde8-a52ae779c726", "quiz": "b0a042c3-329b-50d9-baea-40531f6f5d36", "pos": 6, "kind": "mcq", "prompt": "[Criterion C: Processing and evaluating]\nOn a speed–time graph, what does each shape mean?\nLine sloping downwards", "options": ["Constant speed", "Accelerating", "Decelerating"], "marks": 1, "section": "Criterion C", "correct": 2, "model": "Flat: constant speed; up: accelerating; down: decelerating.", "points": null}, {"id": "96dd1e58-4444-55a8-8f51-5df0ccd57d34", "quiz": "b0a042c3-329b-50d9-baea-40531f6f5d36", "pos": 7, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nA runner covers 120 m in the first 20 s, then rests for 10 s. Calculate her speed while running and describe the graph line while she rests.", "options": [], "marks": 3, "section": "Criterion C", "correct": null, "model": "120 ÷ 20 [1] = 6 m/s [1]; while she rests the line is flat (horizontal) [1].", "points": [{"text": "120 ÷ 20", "any": ["120 ÷ 20", "120/20", "120 / 20"], "all": [], "marks": 1}, {"text": "= 6 m/s", "any": ["6"], "all": [], "marks": 1}, {"text": "While she rests the line is flat (horizontal)", "any": ["flat", "horizontal", "stationary"], "all": [], "marks": 1}]}, {"id": "eda18f7a-e45e-5e78-964c-2ddfc00e9dcc", "quiz": "b0a042c3-329b-50d9-baea-40531f6f5d36", "pos": 8, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nState two rules for drawing a good graph on graph paper.", "options": [], "marks": 2, "section": "Criterion C", "correct": null, "model": "Label both axes with quantities and units [1]; choose a scale that uses more than half the paper and draw a best-fit line with a ruler [1].", "points": [{"text": "Label both axes with quantities and units", "any": ["label", "units", "axes"], "all": [], "marks": 1}, {"text": "Choose a scale that uses more than half the paper and draw a best-fit line with a ruler", "any": ["scale", "ruler", "best fit", "title", "cross", "half"], "all": [], "marks": 1}]}, {"id": "bc0adbf9-db49-569d-8d2d-c0eafc7177a5", "quiz": "7b4c107e-f344-5b55-a083-e0a7d04c77b5", "pos": 1, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nWrite the equation that links speed, distance and time, and rearrange it to find distance.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "Speed = distance ÷ time [1]; distance = speed × time [1].", "points": [{"text": "Speed = distance ÷ time", "any": ["speed = distance", "distance ÷ time", "distance / time", "d ÷ t", "d/t"], "all": [], "marks": 1}, {"text": "Distance = speed × time", "any": ["speed × time", "speed x time", "s × t", "s x t"], "all": [], "marks": 1}]}, {"id": "2d255ff6-e05d-5598-af3a-dd057b8af64a", "quiz": "7b4c107e-f344-5b55-a083-e0a7d04c77b5", "pos": 2, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nA plane flies 1200 km in 1.5 hours. Calculate its average speed.", "options": [], "marks": 2, "section": "Criterion C", "correct": null, "model": "1200 ÷ 1.5 [1] = 800 km/h [1].", "points": [{"text": "1200 ÷ 1.5", "any": ["1200 ÷ 1.5", "1200/1.5", "1200 / 1.5"], "all": [], "marks": 1}, {"text": "= 800 km/h", "any": ["800"], "all": [], "marks": 1}]}, {"id": "56b55130-12b5-580a-862b-ef852e0e4994", "quiz": "7b4c107e-f344-5b55-a083-e0a7d04c77b5", "pos": 3, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nA boda boda travels at 15 m/s for 40 s. Calculate the distance.", "options": [], "marks": 2, "section": "Criterion C", "correct": null, "model": "15 × 40 [1] = 600 m [1].", "points": [{"text": "15 × 40", "any": ["15 × 40", "15 x 40", "15*40"], "all": [], "marks": 1}, {"text": "= 600 m", "any": ["600"], "all": [], "marks": 1}]}, {"id": "b8223bae-f23b-5f6e-9528-54f41452a203", "quiz": "7b4c107e-f344-5b55-a083-e0a7d04c77b5", "pos": 4, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nHow long does a car moving at 25 m/s take to travel 1 km?", "options": [], "marks": 2, "section": "Criterion C", "correct": null, "model": "1000 ÷ 25 [1] = 40 s [1].", "points": [{"text": "1000 ÷ 25", "any": ["1000 ÷ 25", "1000/25", "1000 / 25"], "all": [], "marks": 1}, {"text": "= 40 s", "any": ["40"], "all": [], "marks": 1}]}, {"id": "03c71405-5b32-516f-93c1-e12bb4671108", "quiz": "1a5927e6-1180-5aeb-a787-8d1f541afc11", "pos": 1, "kind": "short", "prompt": "[Criterion B: Inquiring and designing]\nA student wants to find out whether the surface of a ramp (wood, cloth, sandpaper) affects the speed of a toy car. Identify the independent and dependent variables and two control variables.", "options": [], "marks": 4, "section": "Criterion B", "correct": null, "model": "Independent: the surface of the ramp [1]; dependent: the time to travel 1 m (speed) [1]; controls: the same car and ramp height [1], and the same distance and starting position [1].", "points": [{"text": "Independent: the surface of the ramp", "any": ["surface"], "all": [], "marks": 1}, {"text": "Dependent: the time to travel 1 m (speed)", "any": ["speed", "time"], "all": [], "marks": 1}, {"text": "Controls: the same car and ramp height", "any": ["same car", "same height", "same ramp", "height"], "all": [], "marks": 1}, {"text": "The same distance and starting position", "any": ["same distance", "start", "release", "mass", "length"], "all": [], "marks": 1}]}, {"id": "89c1d6d5-d3f0-59b5-93d5-3c97494a9415", "quiz": "1a5927e6-1180-5aeb-a787-8d1f541afc11", "pos": 2, "kind": "short", "prompt": "[Criterion B: Inquiring and designing]\nWrite a hypothesis for this investigation.", "options": [], "marks": 2, "section": "Criterion B", "correct": null, "model": "If the surface is rougher (sandpaper), the car will be slower [1], because there is more friction [1].", "points": [{"text": "If the surface is rougher (sandpaper), the car will be slower", "any": ["rough", "sandpaper", "cloth", "smooth"], "all": [], "marks": 1}, {"text": "Because there is more friction", "any": ["friction", "slower", "slow"], "all": [], "marks": 1}]}, {"id": "a5c3aaca-7d32-54b3-8e0d-4b3a5fb57838", "quiz": "1a5927e6-1180-5aeb-a787-8d1f541afc11", "pos": 3, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nTimes for 1 m on cloth: 1.6, 1.5, 1.7 s. Calculate the mean time and average speed.", "options": [], "marks": 2, "section": "Criterion C", "correct": null, "model": "Mean = (1.6 + 1.5 + 1.7) ÷ 3 = 1.6 s [1]; speed = 1 ÷ 1.6 = 0.63 m/s [1].", "points": [{"text": "Mean = (1.6 + 1.5 + 1.7) ÷ 3 = 1.6 s", "any": ["1.6"], "all": [], "marks": 1}, {"text": "Speed = 1 ÷ 1.6 = 0.63 m/s", "any": ["0.63", "0.625", "0.6"], "all": [], "marks": 1}]}, {"id": "c1724444-d470-57af-b1ff-062f58ca706b", "quiz": "1a5927e6-1180-5aeb-a787-8d1f541afc11", "pos": 4, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nExplain why the experiment should be repeated three times.", "options": [], "marks": 1, "section": "Criterion C", "correct": null, "model": "To identify anomalous results and calculate a mean, so the results are more reliable [1].", "points": [{"text": "To identify anomalous results and calculate a mean, so the results are more reliable", "any": ["reliable", "anomal", "mean", "error", "accurate"], "all": [], "marks": 1}]}, {"id": "716e3a3c-10a4-5baa-96f2-a9dd86357217", "quiz": "cf6d16f0-3bb9-540b-8954-be5e9214289d", "pos": 1, "kin